import * as T from 'three';
function softBox(size,center){const radius=Math.min(size.x,size.y,size.z)*.15,g=new T.BoxGeometry(size.x,size.y,size.z,5,3,5),p=g.attributes.position,half=size.clone().multiplyScalar(.5).addScalar(-radius),v=new T.Vector3(),q=new T.Vector3();for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i);q.copy(v).clamp(half.clone().negate(),half);v.sub(q).normalize().multiplyScalar(radius).add(q).add(center);p.setXYZ(i,...v.toArray());}g.computeVertexNormals();return g;}
export function finishCab180(board){board.traverse(o=>{if(!o.isMesh||o.userData.finish180)return;if(/Placa[_ ]mando149/.test(o.name)){o.geometry.computeBoundingBox();const b=o.geometry.boundingBox;o.geometry=softBox(b.getSize(new T.Vector3()),b.getCenter(new T.Vector3()));}o.userData.finish180=true;});}
export function crisp180(map){map.anisotropy=16;map.generateMipmaps=true;map.minFilter=T.LinearMipmapLinearFilter;map.magFilter=T.LinearFilter;map.colorSpace=T.SRGBColorSpace;return map;}
